ed official bundle:\n    // When candidate name is an existing declared official bundle (e.g. @deepseek-ai/dsh-base),\n    // carrying host dependencies must NOT trigger false-positive blockers.\n    {\n      const p = join(root, \"profiles\", \"web-baseline\");\n      const candUpdateDir = join(root, \"cand-official-update\");\n      mkdirSync(candUpdateDir, { recursive: true });\n      writeFileSync(join(candUpdateDir, \"package.json\"), JSON.stringify({\n        name: \"@deepseek-ai/dsh-base\",\n        version: \"0.1.0-rc.7\",\n        dependencies: {\n          \"@deepseek-ai/dsh-agent\": \"0.1.0-rc.7\",\n          \"@deepseek-ai/dsh-tool-subagent\": \"0.1.0-rc.7\",\n        },\n        dsh: { bundle: { patch: \"./cordis.patch.yml\" } },\n      }));\n      writeFileSync(join(candUpdateDir, \"cordis.patch.yml\"), `\n- insert:\n    - id: agent\n      name: '@deepseek-ai/dsh-agent'\n    - id: tool-subagent\n      name: '@deepseek-ai/dsh-tool-subagent'\n    - id: tool-subagent-fork\n      name: '@deepseek-ai/dsh-tool-subagent'\n`);\n      const repUpdate = inspectCandidate({\n        profileDir: p,\n        candidateManifestPath: join(candUpdateDir, \"package.json\"),\n        spec: \"@deepseek-ai/dsh-base@0.1.0-rc.7\",\n      });\n      if (repUpdate.ok !== true || repUpdate.verdict !== \"safe\" || repUpdate.issues.some((e) => e.severity === \"block\")) {\n        throw new Error(`legitimate official update must validate safe with 0 blockers, got: ${JSON.stringify(repUpdate.issues)}`);\n      }\n    }\n\n    // 8) Direct dependency whose package.json omits or mismatches name:\n    // packageInfo and static validation (validateInstalledProfile) must require\n    // manifest.name === requested packageName, flagging missing or mismatched names as package-unresolved.\n    {\n      // 8A: Omitted name in package.json\n      const pMissing = join(root, \"profiles\", \"pkg-omitted-name\");\n      mkdirSync(join(pMissing, \"node_modules\", \"no-name-pkg\"), { recursive: true });\n      writeFileSync(join(pMissing, \"package.json\"), JSON.stringify({ dependencies: { \"no-name-pkg\": \"1.0.0\" } }));\n      writeFileSync(join(pMissing, \"cordis.patch.yml\"), \"[]\\n\");\n      writeFileSync(join(pMissing, \"node_modules\", \"no-name-pkg\", \"package.json\"), JSON.stringify({ version: \"1.0.0\" }));\n\n      if (packageInfo(\"no-name-pkg\", pMissing) !== undefined) {\n        throw new Error(\"packageInfo must return undefined when package.json omits name\");\n      }\n      const vMissing = validateInstalledProfile(pMissing);\n      if (vMissing.ok !== false || vMissing.verdict !== \"blocked\" || !vMissing.issues.some((e) => e.code === \"package-unresolved\" && e.package === \"no-name-pkg\")) {\n        throw new Error(\"validateInstalledProfile must block with package-unresolved when package.json omits name\");\n      }\n\n      // 8B: Mismatched name in package.json\n      const pMismatch = join(root, \"profiles\", \"pkg-mismatched-name\");\n      mkdirSync(join(pMismatch, \"node_modules\", \"expected-name\"), { recursive: true });\n      writeFileSync(join(pMismatch, \"package.json\"), JSON.stringify({ dependencies: { \"expected-name\": \"1.0.0\" } }));\n      writeFileSync(join(pMismatch, \"cordis.patch.yml\"), \"[]\\n\");\n      writeFileSync(join(pMismatch, \"node_modules\", \"expected-name\", \"package.json\"), JSON.stringify({ name: \"actual-other-name\", version: \"1.0.0\" }));\n\n      if (packageInfo(\"expected-name\", pMismatch) !== undefined) {\n        throw new Error(\"packageInfo must return undefined when package.json has mismatched name\");\n      }\n      const vMismatch = validateInstalledProfile(pMismatch);\n      if (vMismatch.ok !== false || vMismatch.verdict !== \"blocked\" || !vMismatch.issues.some((e) => e.code === \"package-unresolved\" && e.package === \"expected-name\")) {\n        throw new Error(\"validateInstalledProfile must block with package-unresolved when package.json has mismatched name\");\n      }\n    }\n\n    // ── 取消传播（spawnCapture / preflightInstall）─────────────────────────\n    //\n    // 预检是 market_install 里唯一真正耗时的一段（隔离目录探装）。它此前完全\n    // 不可取消：按下 job_kill 只是标记了记录，pnpm 照跑到底。这三条钉的是\n    // 取消语义本身——不 spawn、等 close、以及「取消不是一份阻断报告」。\n    {\n      const marker = join(root, \"child-ran.txt\");\n      const writeMarker = `require(\"node:fs\").writeFileSync(${JSON.stringify(marker)}, \"ran\")`;\n\n      // 1) 已经取消 → 一个子进程都不该起。\n      const preAborted = await _spawnCaptureForTests(\n        process.execPath,\n        [\"-e\", writeMarker],\n        { env: process.env },\n        undefined,\n        { signal: AbortSignal.abort() },\n      );\n      if (preAborted.aborted !== true) throw new Error(\"已 abort 的 signal 必须标记 aborted\");\n      if (existsSync(marker)) throw new Error(\"已 abort 的 signal 仍然 spawn 了子进程\");\n      console.log(\"PASS 取消：已 abort 的 signal 不 spawn 子进程\");\n\n      // 2) 飞行中取消 → 杀掉子进程，但仍然等到 'close' 才 resolve。\n      //    （resolve 早于进程退出，调用方就会在 pnpm 还在写的时候删 probe 目录。）\n      const controller = new AbortController();\n      const startedAt = Date.now();\n      let closedAt;\n      const running = _spawnCaptureForTests(\n        process.execPath,\n        [\"-e\", `process.on(\"exit\", () => {}); setTimeout(() => { ${writeMarker} }, 30000)`],\n        { env: process.env },\n        undefined,\n        { signal: controller.signal, treeKill: false },\n      ).then((result) => { closedAt = Date.now(); return result; });\n      await new Promise((r) => setTimeout(r, 150));\n      controller.abort();\n      const killed = await running;\n      const elapsed = closedAt - startedAt;\n      if (killed.aborted !== true) throw new Error(\"飞行中取消必须标记 aborted\");\n      if (elapsed > 20000) throw new Error(`取消后应立即终止子进程，实测等了 ${elapsed}ms`);\n      if (existsSync(marker)) throw new Error(\"取消后子进程仍然跑完了它的工作\");\n      console.log(`PASS 取消：飞行中取消终止子进程并等到 close 才 resolve（${elapsed}ms）`);\n\n      // 3) preflightInstall 取消 → 抛 AbortError，而不是返回一份 blocked 报告。\n      //    兜底 catch 会把任何异常变成「预检执行失败」的阻断结论；那份结论会\n      //    被上层缓存、展示成候选包的问题，而用户只是按了取消。\n      let cancelOutcome = \"<resolved>\";\n      try {\n        const report = await preflightInstall({ profileDir, spec: \"any-package\", signal: AbortSignal.abort() });\n        cancelOutcome = `report:${report.verdict}`;\n      } catch (error) {\n        cancelOutcome = isAbortError(error) ? \"abort\" : `error:${error?.name}`;\n      }\n      if (cancelOutcome !== \"abort\") throw new Error(`preflightInstall 取消必须上抛 AbortError，实得 ${cancelOutcome}`);\n      console.log(\"PASS 取消：preflightInstall 上抛 AbortError（不伪造阻断报告）\");\n\n      // 4) 探针目录删不掉时，清理不许改变结局。\n      //    实测踩到的：取消后 taskkill /T /F 一发，wrapper 的 'close' 立刻到，\n      //    但探针目录是那个被强杀的 pnpm 的 cwd，Windows 会一直锁着它，\n      //    finally 里的 rmSync 撞 EPERM —— 而 finally 抛出的异常会顶掉正在\n      //    上抛的 AbortError，于是「用户按了取消」在 job 里显示成一条看不懂的\n      //    EPERM 临时目录路径。\n      //    这里注入一个必抛的 remove：真实 EPERM 靠的是 OS 时序，fixture 复现\n      //    不稳定（Node 的 openSync 带 FILE_SHARE_DELETE，占着句柄照样能删），\n      //    而要钉住的本来就是我们的错误处理，不是内核的时机。\n      const cleanupDir = mkdtempSync(join(tmpdir(), \"dsh-guard-cleanup-\"));\n      let cleanupThrew;\n      let cleanupReport = \"\";\n      try {\n        cleanupProbeDir(cleanupDir, (text) => { cleanupReport += text; }, () => {\n          const error = new Error(`EPERM, Permission denied: ${cleanupDir}`);\n          error.code = \"EPERM\";\n          throw error;\n        });\n      } catch (error) {\n        cleanupThrew = error;\n      }\n      if (cleanupThrew !== undefined) {\n        throw new Error(`cleanupProbeDir 抛了 ${cleanupThrew?.code ?? cleanupThrew?.message}——它跑在 finally 里，会顶掉 AbortError`);\n      }\n      if (!cleanupReport.includes(\"could not remove probe directory\")) {\n        throw new Error(\"清理失败必须被报告出来，而不是静默吞掉\");\n      }\n      // 真能删的时候要真的删掉——上面那条别把清理本身测没了。\n      cleanupProbeDir(cleanupDir, undefined);\n      if (existsSync(cleanupDir)) throw new Error(\"cleanupProbeDir 未能删除可删除的目录\");\n      console.log(\"PASS 取消：探针目录清理失败不改变结局（且可删时确实删掉）\");\n    }\n\n    console.log(\"PASS conflict scan and snapshot/pending/rollback fixtures\");\n  } finally {\n    rmSync(root, { recursive: true, force: true });\n  }\n}\n\nif (process.argv[1]?.endsWith(\"guard.js\") && process.argv.includes(\"--self-test\")) {\n  selfTest().catch((error) => {\n    console.error(`FAIL ${error.stack ?? error.message}`);\n    process.exitCode = 1;\n  });\n}\n"
